      let data = raw ? JSON.parse(raw) : null;
      if (!data) {
        const legacy = storageGet(LEGACY_KEY);
        if (legacy) data = migrateLegacy(JSON.parse(legacy));
      }
      if (!data?.state) throw new Error("bad save");
      const fresh = freshState();
