  function importSaveFile(file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result);
        if (!data.state || !Array.isArray(data.state.party) || !data.state.player || !MAPS[data.state.zone])
          throw Error("invalid");
        const clean = freshState();
        mergeState(clean, data.state);
        if (clean.party.some(
          (p) => !PARTY_DEFS[p.name] || ![p.hp, p.mp, p.maxHp, p.maxMp, p.atk, p.def, p.mag].every(
            Number.isFinite
          )
        ))
          throw Error("invalid");
        storageSet(
          SAVE_KEY,
          JSON.stringify({
            version: VERSION,
            state: clean
          })
        );
        modal = null;
        loadGame();
      } catch (e) {
        notify("SAVE FILE COULD NOT BE READ");
      }
    };
    reader.readAsText(file);
  }
