  function tileRect(key, x, y, w, h, size = 64) {
    const r = TILE[key];
    if (!atlasReady || !r) return;
    const cacheKey = key + ":" + r.join(",") + ":" + size;
    let pattern = tilePatterns.get(cacheKey);
    if (!pattern) {
      const tile = document.createElement("canvas");
      tile.width = size;
      tile.height = size;
      const tc = tile.getContext("2d");
      tc.imageSmoothingEnabled = false;
      tc.drawImage(atlas, ...r, 0, 0, size, size);
      pattern = ctx.createPattern(tile, "repeat");
      tilePatterns.set(cacheKey, pattern);
    }
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = pattern;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  }
  function miniMap(x, y, w, h, z = state.zone, details = false) {
    const m = MAPS[z], sc = Math.min(w / m.w, h / m.h), ox = x + (w - m.w * sc) / 2, oy = y + (h - m.h * sc) / 2;
    ctx.drawImage(districtScene(z, true), ox, oy, m.w * sc, m.h * sc);
    ctx.fillStyle = "#0a24351f";
    ctx.fillRect(ox, oy, m.w * sc, m.h * sc);
    const dot = (px, py, c, r) => {
      ctx.beginPath();
      ctx.fillStyle = c;
      ctx.arc(ox + px * sc, oy + py * sc, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = "#102832";
      ctx.lineWidth = 1;
      ctx.stroke();
    };
    if (z === state.zone) {
      if (details) {
        npcList().forEach((n) => dot(n.x, n.y, "#8ce3d0", 4));
        WORLD_ENCOUNTERS[z].filter((m2) => !state.defeated[mobKey(z, m2.id)]).forEach((m2) => dot(m2.x, m2.y, "#ed9987", 4));
        interactables().filter((i) => !i.hidden?.()).forEach(
          (it) => dot(
            it.x,
            it.y,
            it.travel ? "#c5dce0" : it.id === "rest" ? "#9bdda9" : "#b9bba1",
            4
          )
        );
        const ob = localObjective();
        if (ob) {
          const path = findPath(state.player, ob);
          ctx.strokeStyle = "#f9d98ccc";
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(ox + state.player.x * sc, oy + state.player.y * sc);
          path.forEach((p) => ctx.lineTo(ox + p.x * sc, oy + p.y * sc));
          ctx.stroke();
          dot(ob.x, ob.y, UI_GOLD, 7);
        }
      }
      dot(state.player.x, state.player.y, "#fff7d1", details ? 6 : 3);
    }
  }
