      kind: caster ? "magic" : "physical",
      label: e.resolveTurns ? "RESOLVE \xB7 strike" : e.boss && e.hp / e.maxHp < 0.4 ? "FURY \xB7 strong strike" : caster ? "Signal strike" : "Physical strike",
